{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Alprazolam, a high-transfer lipophilic heteroaromatic drug, has absolute oral bioavailability of 80–100% in humans after a 1 mg oral dose, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Suvorexant, a high-transfer CNS-active drug, has absolute oral bioavailability of 82% under fasted conditions in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Clobazam, a chloro-substituted heteroaromatic drug with high transferability, is 90–100% bioavailable after oral administration in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Ranitidine, a basic amine-containing drug with high transferability, has mean absolute oral bioavailability of 0.60 (range 0.35–0.79) after oral tablet versus IV in healthy volunteers; even the lower end exceeds the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Clonidine, a high-transfer imidazoline, has mean oral bioavailability of 75.2% (70.6–81.5%) versus IV in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Maribavir, a high-transfer orally administered drug, has oral bioavailability of 30–40% in humans, the lowest among the key analogues but still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "High: multiple high-transfer human absolute bioavailability measurements (80–100%, 82%, 90–100%, ~60%, ~75%, 30–40%) all exceed 20%, and no affirmative evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule.",
    "No human PK data are available for the specific 4-aminoquinoline scaffold with the dimethylaminomethylbenzyl side chain.",
    "Metabolism and first-pass effects for the query are inferred from analogues rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

